def climb_stairs(n: int) -> int:
    if n <= 2:
        return n
    a, b = 1, 2  # dp[1], dp[2]
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b


def main():
    n = int(input())
    print(climb_stairs(n))


if __name__ == "__main__":
    main()

def mat_mul(a, b):
    return [
        [a[0][0]*b[0][0] + a[0][1]*b[1][0], a[0][0]*b[0][1] + a[0][1]*b[1][1]],
        [a[1][0]*b[0][0] + a[1][1]*b[1][0], a[1][0]*b[0][1] + a[1][1]*b[1][1]],
    ]


def mat_pow(m, p):
    res = [[1, 0], [0, 1]]
    while p:
        if p & 1:
            res = mat_mul(res, m)
        m = mat_mul(m, m)
        p >>= 1
    return res


def climb_stairs(n: int) -> int:
    if n <= 2:
        return n
    m = [[1, 1], [1, 0]]
    return mat_pow(m, n - 1)[0][0]


def main():
    n = int(input())
    print(climb_stairs(n))


if __name__ == "__main__":
    main()
